# Plan: We need to find the writer of a song inspired by words on a tombstone that was also the first track of the Back to Mono box set.
combi_search_matches = search_context("song inspired by words on a tombstone and first track Back to Mono box set")

if combi_search_matches:
    for match in combi_search_matches:
        words = match.split()

        phrase = ' '.join(words[:len(words)])
        if phrase.lower() == "the first track of":
            next_index_to_check = 6  
            title_writer_found = ' '.join(words[next_index_to_check:])

            found_title_match = search_context(title_writer_found + "' written")

            if len(found_title_match) > 0:
                result = found_title_match[-1].split()[-2:]

                print(result)
                break
else:
    potential_writer_found = search_context("Back to Mono first track written")

    if len(potential_writer_found) > 0:
        result = ' '.join(potential_writer_found[0].split()[-3:])

print('Writer of Song:', result)
